public static class Solution
{
    public static int CountOccurrences(string text, string substring)
    {
        if (string.IsNullOrEmpty(substring))
        {
            return 0;
        }

        int count = 0;
        int index = 0;
        while ((index = text.IndexOf(substring, index)) >= 0)
        {
            count++;
            index++;
        }

        return count;
    }
}

