public static class Solution
{
    public static string RemoveDuplicates(string s)
    {
        var chars = s.ToCharArray();
        Array.Sort(chars);
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < chars.Length; i++)
        {
            if (i == 0 || chars[i] != chars[i - 1])
            {
                sb.Append(chars[i]);
            }
        }
        return sb.ToString();
    }
}

