public record Person(string Name, int Age);

public static class Solution
{
    public static List<string> GetAdultNamesSorted(List<Person> people)
    {
        return people
            .Where(p => p.Age >= 18)
            .OrderBy(p => p.Name)
            .Select(p => p.Name)
            .ToList();
    }
}

