public record NumberPartition(List<int> Evens, List<int> Odds);

public static class Solution
{
    public static NumberPartition PartitionNumbers(List<int> numbers)
    {
        var evens = numbers.Where(n => n % 2 == 0).ToList();
        var odds = numbers.Where(n => n % 2 != 0).ToList();
        return new NumberPartition(evens, odds);
    }
}

