public static class Solution
{
    public static Dictionary<string, int> CountByParity(List<int> nums)
    {
        var counts = new Dictionary<string, int>
        {
            ["Even"] = 0,
            ["Odd"] = 0
        };

        foreach (int num in nums)
        {
            if (num % 2 == 0)
            {
                counts["Even"]++;
            }
            else
            {
                counts["Odd"]++;
            }
        }

        return counts;
    }
}

public record Student(string Name, int Score);
public static class Solution
{
    public static List<string> TopStudents(List<Student> students, int n)
    {
        if (n <= 0)
        {
            return new List<string>();
        }

        return students
            .OrderByDescending(s => s.Score)
            .ThenBy(s => s.Name, StringComparer.Ordinal)
            .Take(n)
            .Select(s => s.Name)
            .ToList();
    }
}

public static class Solution
{
    public static List<string> DistinctOrderedWords(List<string> words)
    {
        return words
